            private void AddCore(ListViewItem item, int position)
            {
                item._listView = _owner;
                item.Index = Count;
                if (item.Group == null)
                    item.Group = _owner.DefaultGroup;

                base.Add(item);
                _owner.NativeAdd(item, position);
