    public void Refresh()
    {
        if ((_list?.Count ?? 0) <= 0)
        {
            ListPosition = -1;
        }
        else if (ListPosition >= (_list?.Count ?? 0))
        {
            _lastGoodKnownRow = -1;
            ListPosition = 0;
        }
        List_ListChanged(_list, new ListChangedEventArgs(ListChangedType.Reset, -1));
    }

    internal void Release()
