using Cairo;
using GLib;
using System.ComponentModel;

namespace System.Windows.Forms
{
    public abstract class FileDialog : CommonDialog
    {
        public FileDialog()
        {

        }
        public bool ValidateNames { get; set; }

        public string Title { get; set; }

        public bool SupportMultiDottedExtensions { get; set; }

        public bool ShowHelp { get; set; }

        public bool RestoreDirectory { get; set; }

        public string InitialDirectory { get; set; }
        public string Description { get; set; }
        internal bool Multiselect { get; set; }
        public int FilterIndex { get; set; }

        private string _filter;
        public string Filter
        {
            get
            {
                return _filter ?? string.Empty;
            }
            set
            {
                if (value == _filter)
                {
                    return;
                }
                if (!string.IsNullOrEmpty(value))
                {
                    string[] filters = value.Split('|');
                    int pipeCount = filters.Length;
                    if (pipeCount == 1 || pipeCount % 2 == 1)
                    {
                        throw new ArgumentException("FileDialog Invalid Filter", value);
                    }
                    for(int i = 1; i < pipeCount; i += 2)
                    {
                        if (filters[i].Split('.').Length == 1)
                        {
                            throw new ArgumentException("FileDialog Invalid Filter", value);
                        }
                    }
                }
                else
                {
                    value = null!;
                }

                _filter = value;
            }
        }

        public bool AutoUpgradeEnabled { get; set; }
        internal string SelectedDirectory { get; set; }
        public string FileName { get; set; }
        public string[] FileNames { get; internal set; }
        public bool DereferenceLinks { get; set; }

        public string DefaultExt { get; set; }

        public bool CheckPathExists { get; set; }

        public virtual bool CheckFileExists { get; set; }

        public bool AddExtension { get; set; }

        public event CancelEventHandler FileOk;
        internal Gtk.FileChooserAction ActionType { get; set; }
        public override void Reset()
        {
            AddExtension = true;
            Title = null;
            InitialDirectory = null;
            FileName = null;
            FileNames = null;
            _filter = null;
            FilterIndex = 1;
            SupportMultiDottedExtensions = false;
        }
        protected override bool RunDialog(IWin32Window owner)
        {
            Gtk.FileChooserDialog fileDialog = null;
            if (owner != null && owner is Form ownerform)
            {
                fileDialog = new Gtk.FileChooserDialog(Properties.Resources.Gtk_FileDialog_RunDialog_Select_File, ownerform.self, ActionType);
                fileDialog.WindowPosition = Gtk.WindowPosition.CenterOnParent;
            }
            else
            {
                fileDialog = new Gtk.FileChooserDialog(Properties.Resources.Gtk_FileDialog_RunDialog_Select_File, null, ActionType);
                fileDialog.WindowPosition = Gtk.WindowPosition.Center;
            }
            fileDialog.IconName = "document-open";
            fileDialog.AddButton(Properties.Resources.Gtk_FileDialog_RunDialog_OK, Gtk.ResponseType.Ok);
            fileDialog.AddButton(Properties.Resources.Gtk_MessageBox_ShowCore_Cancel, Gtk.ResponseType.Cancel);
            fileDialog.SelectMultiple = this.Multiselect;
            fileDialog.Title = this.Title ?? string.Empty;
            fileDialog.TooltipText = this.Description ?? string.Empty;

            fileDialog.KeepAbove = true;
            if (!string.IsNullOrWhiteSpace(this.SelectedDirectory))
                fileDialog.SetCurrentFolder(this.SelectedDirectory);
            else if (!string.IsNullOrWhiteSpace(this.InitialDirectory))
                fileDialog.SetCurrentFolder(this.InitialDirectory);


            if (_filter != null)
            {
                string[] filters = _filter.Split('|');
                for (int i = 1; i < filters.Length; i += 2)
                {
                    string[] patterns = filters[i].Split(';');
                    foreach (string pattern in patterns)
                    {
                        Gtk.FileFilter ffilter = new Gtk.FileFilter();
                        string extand = pattern.TrimStart(new char[] { '*', ' ' });
                        if (MimeMapping.ContainsKey(extand))
                        {
                            ffilter.AddMimeType(MimeMapping[extand]);
                        }
                        ffilter.AddPattern(pattern);
                        ffilter.Name = $"{filters[i - 1]}（{pattern}）";
                        fileDialog.AddFilter(ffilter);
                        if(pattern== DefaultExt)
                        {
                            fileDialog.Filter = ffilter;
                        }
                    }
                }
            }
            int response = fileDialog.Run();
            this.FileName = fileDialog.Filename;
            this.FileNames = fileDialog.Filenames.Clone() as string[];
            this.SelectedDirectory = fileDialog.Filename;
            fileDialog.Dispose();
            fileDialog.Destroy();
            return response == -5;
        }
        static Dictionary<string, string> MimeMapping = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
