            Graphics graphics,
            Font? font,
            Rectangle rect,
            int index,
            DrawItemState state,
            Color foreColor,
            Color backColor)
        {
            this.graphics=graphics ?? throw new ArgumentNullException(nameof(graphics));
            this.Bounds = rect;
            Font = font;
            Index = index;
            State = state;
            _foreColor = foreColor;
            _backColor = backColor;
        }
