    public enum MessageBoxIcon
    {
        /// <summary>
        ///  Specifies that the message box contain no symbols.
        /// </summary>
        None = 0,

        /// <summary>
        ///  Specifies that the message box contains a hand symbol.
        /// </summary>
        Hand = 0x00000010,

        /// <summary>
        ///  Specifies that the message box contains a question mark symbol.
        /// </summary>
