				{
					if (s_imageInfoList == null)
					{
						s_imageInfoList = new List<ImageInfo>();
					}
					imageInfo.FrameChangedHandler = onFrameChangedHandler;
					s_imageInfoList.Add(imageInfo);
					if (s_animationThread == null)
					{
