			{
				return;
			}
			bool isReaderLockHeld = s_rwImgListLock.IsReaderLockHeld;
			LockCookie lockCookie = default(LockCookie);
			t_threadWriterLockWaitCount++;
			try
			{
				if (isReaderLockHeld)
				{
					lockCookie = s_rwImgListLock.UpgradeToWriterLock(-1);
				}
				else
				{
					s_rwImgListLock.AcquireWriterLock(-1);
				}
			}
			finally
			{
				t_threadWriterLockWaitCount--;
			}
			try
			{
				for (int i = 0; i < s_imageInfoList.Count; i++)
				{
					ImageInfo imageInfo = s_imageInfoList[i];
					if (image == imageInfo.Image)
					{
						if ((Delegate?)onFrameChangedHandler == (Delegate?)imageInfo.FrameChangedHandler || (onFrameChangedHandler != null && onFrameChangedHandler.Equals(imageInfo.FrameChangedHandler)))
						{
							s_imageInfoList.Remove(imageInfo);
						}
						break;
					}
				}
			}
			finally
			{
				if (isReaderLockHeld)
				{
					s_rwImgListLock.DowngradeFromWriterLock(ref lockCookie);
				}
				else
				{
					s_rwImgListLock.ReleaseWriterLock();
				}
			}
		}

		private static void AnimateImages()
		{
			Stopwatch stopwatch = Stopwatch.StartNew();
			while (true)
			{
				Thread.Sleep(40);
				long elapsedMilliseconds = stopwatch.ElapsedMilliseconds;
				stopwatch.Restart();
				s_rwImgListLock.AcquireReaderLock(-1);
				try
				{
					for (int i = 0; i < s_imageInfoList.Count; i++)
					{
						ImageInfo imageInfo = s_imageInfoList[i];
						if (imageInfo.Animated)
						{
							imageInfo.AdvanceAnimationBy(elapsedMilliseconds);
							if (imageInfo.FrameDirty)
							{
								s_anyFrameDirty = true;
							}
						}
					}
				}
				finally
				{
					s_rwImgListLock.ReleaseReaderLock();
				}
			}
		}
	}
}

using System.Buffers.Binary;
using System.ComponentModel;
using System.Diagnostics.CodeAnalysis;
using System.Drawing.Imaging;
using System.Globalization;
using System.IO;

namespace System.Drawing
{
	public class ImageConverter : TypeConverter
	{
		public override bool CanConvertFrom(ITypeDescriptorContext context, Type sourceType)
		{
			//if (!(sourceType == typeof(byte[])))
			//{
			//	return sourceType == typeof(Icon);
			//}
			return true;
		}

		public override bool CanConvertTo(ITypeDescriptorContext context, [NotNullWhen(true)] Type destinationType)
		{
			if (!(destinationType == typeof(byte[])))
			{
				return destinationType == typeof(string);
			}
			return true;
		}

		public override object ConvertFrom(ITypeDescriptorContext context, CultureInfo culture, object value)
		{
			//Icon icon = value as Icon;
			//if (icon != null)
			//{
			//	return icon.ToBitmap();
			//}
			byte[] array = value as byte[];
			if (array != null)
			{
				Stream stream = GetBitmapStream(array) ?? new MemoryStream(array);
				return Image.FromStream(stream);
			}
			return base.ConvertFrom(context, culture, value);
		}

		public override object ConvertTo(ITypeDescriptorContext context, CultureInfo culture, object value, Type destinationType)
		{
			if (destinationType == typeof(string))
			{
				if (value == null)
				{
					return "none";
				}
				if (value is Image)
				{
					return value!.ToString();
				}
			}
			else if (destinationType == typeof(byte[]))
			{
				if (value == null)
				{
					return Array.Empty<byte>();
				}
				Image image = value as Image;
				if (image != null)
				{
					using (MemoryStream memoryStream = new MemoryStream())
					{
						ImageFormat imageFormat = image.RawFormat;
						if (imageFormat == ImageFormat.Jpeg)
						{
							imageFormat = ImageFormat.Png;
						}
						ImageCodecInfo encoder = FindEncoder(imageFormat) ?? FindEncoder(ImageFormat.Png);
						image.Save(memoryStream, encoder, null);
						return memoryStream.ToArray();
					}
				}
			}
			throw GetConvertFromException(value);
		}

		private static ImageCodecInfo FindEncoder(ImageFormat imageformat)
		{
			ImageCodecInfo[] imageEncoders = ImageCodecInfo.GetImageEncoders();
			ImageCodecInfo[] array = imageEncoders;
			foreach (ImageCodecInfo imageCodecInfo in array)
			{
				if (imageCodecInfo.FormatID.Equals(imageformat.Guid))
				{
					return imageCodecInfo;
				}
			}
			return null;
		}

		//[RequiresUnreferencedCode("The Type of value cannot be statically discovered. The public parameterless constructor or the 'Default' static field may be trimmed from the Attribute's Type.")]
		public override PropertyDescriptorCollection GetProperties(ITypeDescriptorContext context, object value, Attribute[] attributes)
		{
			return TypeDescriptor.GetProperties(typeof(Image), attributes);
		}

		public override bool GetPropertiesSupported(ITypeDescriptorContext context)
		{
			return true;
		}

		private static Stream GetBitmapStream(ReadOnlySpan<byte> rawData)
		{
			try
			{
				short num = BinaryPrimitives.ReadInt16LittleEndian(rawData);
				if (num != 7189)
				{
					return null;
				}
				short num2 = BinaryPrimitives.ReadInt16LittleEndian(rawData.Slice(2, 2));
				if (rawData.Length <= num2 + 18 || !rawData.Slice(num2 + 12, 6).SequenceEqual(new byte[6] { 80, 66, 114, 117, 115, 104 }))
				{
					return null;
				}
				return new MemoryStream(rawData.Slice(78).ToArray());
			}
			catch (OutOfMemoryException)
			{
			}
			catch (ArgumentOutOfRangeException)
			{
			}
			return null;
		}
	}
}

using System.ComponentModel;
using System.ComponentModel.Design.Serialization;
using System.Diagnostics.CodeAnalysis;
using System.Drawing.Imaging;
using System.Globalization;
using System.Reflection;

namespace System.Drawing
{
	public class ImageFormatConverter : TypeConverter
	{
		public override bool CanConvertFrom(ITypeDescriptorContext context, Type sourceType)
		{
			if (!(sourceType == typeof(string)))
			{
				return base.CanConvertFrom(context, sourceType);
			}
			return true;
		}

		public override bool CanConvertTo(ITypeDescriptorContext context, [NotNullWhen(true)] Type destinationType)
		{
			if (destinationType == typeof(string) || destinationType == typeof(InstanceDescriptor))
			{
				return true;
			}
			return base.CanConvertTo(context, destinationType);
		}

		public override object ConvertFrom(ITypeDescriptorContext context, CultureInfo culture, object value)
		{
			string text = value as string;
			if (text == null)
			{
				return base.ConvertFrom(context, culture, value);
			}
			if (text[0] == '[' && text.Length >= 50 && Guid.TryParse(text.Substring(14, 36), out var result))
			{
				return new ImageFormat(result);
			}
			if (text.Equals("Bmp", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Bmp;
			}
			if (text.Equals("Emf", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Emf;
			}
			if (text.Equals("Exif", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Exif;
			}
			if (text.Equals("Gif", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Gif;
			}
			if (text.Equals("Icon", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Icon;
			}
			if (text.Equals("Jpeg", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Jpeg;
			}
			if (text.Equals("MemoryBmp", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.MemoryBmp;
			}
			if (text.Equals("Png", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Png;
			}
			if (text.Equals("Tiff", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Tiff;
			}
			if (text.Equals("Wmf", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Wmf;
			}
			if (text.Equals("Heif", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Heif;
			}
			if (text.Equals("Webp", StringComparison.OrdinalIgnoreCase))
			{
				return ImageFormat.Webp;
			}
			throw new FormatException("ImageFormat err");
		}

		public override object ConvertTo(ITypeDescriptorContext context, CultureInfo culture, object value, Type destinationType)
		{
			ImageFormat imageFormat = value as ImageFormat;
			if (imageFormat != null)
			{
				if (destinationType == typeof(string))
				{
					return imageFormat.ToString();
				}
				if (destinationType == typeof(InstanceDescriptor))
				{
					string text = null;
					if (imageFormat.Guid.Equals(ImageFormat.Bmp.Guid))
					{
						text = "Bmp";
					}
					else if (imageFormat.Guid.Equals(ImageFormat.Emf.Guid))
					{
						text = "Emf";
					}
					else if (imageFormat.Guid.Equals(ImageFormat.Exif.Guid))
					{
						text = "Exif";
					}
					else if (imageFormat.Guid.Equals(ImageFormat.Gif.Guid))
					{
						text = "Gif";
					}
					else if (imageFormat.Guid.Equals(ImageFormat.Icon.Guid))
					{
						text = "Icon";
					}
					else if (imageFormat.Guid.Equals(ImageFormat.Jpeg.Guid))
					{
						text = "Jpeg";
					}
					else if (imageFormat.Guid.Equals(ImageFormat.MemoryBmp.Guid))
					{
						text = "MemoryBmp";
					}
					else if (imageFormat.Guid.Equals(ImageFormat.Png.Guid))
					{
						text = "Png";
					}
					else if (imageFormat.Guid.Equals(ImageFormat.Tiff.Guid))
					{
						text = "Tiff";
					}
					else if (imageFormat.Guid.Equals(ImageFormat.Wmf.Guid))
					{
						text = "Wmf";
					}
					if (text != null)
					{
						return new InstanceDescriptor(typeof(ImageFormat).GetProperty(text), null);
					}
					ConstructorInfo constructor = typeof(ImageFormat).GetConstructor(new Type[1] { typeof(Guid) });
					return new InstanceDescriptor(constructor, new object[1] { imageFormat.Guid });
				}
			}
			return base.ConvertTo(context, culture, value, destinationType);
		}

		public override StandardValuesCollection GetStandardValues(ITypeDescriptorContext context)
		{
			return new StandardValuesCollection(new ImageFormat[12]
			{
				ImageFormat.MemoryBmp,
				ImageFormat.Bmp,
				ImageFormat.Emf,
				ImageFormat.Wmf,
				ImageFormat.Gif,
				ImageFormat.Jpeg,
				ImageFormat.Png,
				ImageFormat.Tiff,
				ImageFormat.Exif,
				ImageFormat.Icon,
				ImageFormat.Heif,
				ImageFormat.Webp
			});
		}

		public override bool GetStandardValuesSupported(ITypeDescriptorContext context)
		{
			return true;
		}
	}
}

